import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {pathToFileURL} from 'node:url';
export function nativeMetadata(health,listing,props,model,context,baseUrl){
 assert.equal(health?.status,'ok','Native server is not healthy');
 assert.ok(Array.isArray(listing?.data)&&listing.data.length===1,'Native discovery is ambiguous');
 assert.equal(listing.data[0].id,model,'Native alias changed');
 assert.equal(props?.model_alias,model,'Native props alias changed');
 assert.equal(props?.total_slots,1,'Native control is not single-slot');
 const capacity=props?.default_generation_settings?.n_ctx;
 assert.ok(Number.isSafeInteger(capacity)&&capacity>=4000&&capacity<=1048576,'Native context metadata is invalid');
 assert.ok(Number.isSafeInteger(context)&&context>=4000&&context===capacity,'Native context differs from the control');
 return {baseUrl,model,context};
}
async function fetchJSON(url){
 const response=await fetch(url,{signal:AbortSignal.timeout(10000)});assert.ok(response.ok,'Native discovery HTTP failed');
 const text=await response.text();assert.ok(Buffer.byteLength(text)<=2097152,'Native metadata is oversized');return JSON.parse(text);
}
if(import.meta.url===pathToFileURL(process.argv[1]).href){
 const [configPath,baseUrl,rawContext,model,output,binary]=process.argv.slice(2);
 const config=JSON.parse(await readFile(configPath,'utf8'));
 const {evaluate}=await import(pathToFileURL(config.decode_source+'/tools/openclaw_eval.mjs').href);
 const url=new URL(baseUrl);assert.equal(url.hostname,'127.0.0.1');assert.equal(url.pathname,'/v1');
 const context=Number(rawContext);
 const discover=async()=>{
  const [health,listing,props]=await Promise.all([fetchJSON(new URL('/health',url)),fetchJSON(new URL('/v1/models',url)),fetchJSON(new URL('/props',url))]);
  return nativeMetadata(health,listing,props,model,context,baseUrl);
 };
 // Only metadata discovery is adapted. The real client, fixture verifier and
 // every inference/tool request use the unmodified direct native endpoint.
 const summary=await evaluate({baseUrl,context,output,binary,timeout:300},{discover});
 process.exitCode=summary.passed?0:1;
}
